const source = $json.source ?? 'pdf_webhook';
const extracted =
  $json.letter_text ??
  $json.text ??
  $json.data ??
  $json.content ??
  '';

const text = String(extracted).replace(/\u0000/g, '').trim();
const filename =
  $json.original_filename ??
  $binary?.data?.fileName ??
  'unknown.pdf';

// Data minimisation, not full anonymisation:
// remove contact channels and financial identifiers that the legal workflow
// doesn't need. Names and authority/case references remain because matching
// may require them.
const minimised = text
  .replace(/\b[A-Z]{2}\d{2}(?:\s?\d{4}){3,7}\b/gi, '[IBAN REDACTED]')
  .replace(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi, '[EMAIL REDACTED]')
  .replace(/(?:\+49|0)[\d\s()/-]{7,}/g, '[PHONE REDACTED]')
  .slice(0, 20000);

const warnings = [];
if (text.length < 80) warnings.push('TEXT_TOO_SHORT_OR_SCAN');
if (text.length > 20000) warnings.push('TEXT_TRUNCATED_AT_20000_CHARS');

return [{
  json: {
    source,
    original_filename: filename,
    source_document_id: `${$execution.id}:${filename}`,
    original_text_length: text.length,
    minimised_text: minimised,
    intake_warnings: warnings,
    received_at: new Date().toISOString(),
  }
}];

const intake = $('Normalize & Minimise').first().json;
const response = $json;
const artifacts = response.artefacts ?? {};
const classification = artifacts.classification ?? {};
const deadline = artifacts.frist ?? {};
const matched = artifacts.matched_case ?? null;
const demanded = artifacts.required_documents ?? [];

const blockers = [];
const warnings = [...(intake.intake_warnings ?? [])];

if (!matched) blockers.push('CASE_MATCH_REQUIRED');
if (response.status !== 'completed') blockers.push('AGENT_NOT_COMPLETED');
if (deadline.raw_text && !deadline.deadline_iso) blockers.push('RELATIVE_OR_UNRESOLVED_DEADLINE');
if (classification.urgency === 'hoch') warnings.push('HIGH_URGENCY');
if (!deadline.deadline_iso && ['anhoerung', 'bescheid_negativ', 'terminladung'].includes(classification.letter_type)) {
  blockers.push('POSSIBLE_DEADLINE_MISSING');
}

const nextActions = [];
if (deadline.deadline_iso) {
  nextActions.push({
    type: 'create_deadline_task',
    due_date: deadline.deadline_iso,
    title: `${classification.letter_type ?? 'Behördenbrief'} prüfen und bearbeiten`,
  });
}
if (demanded.length) {
  nextActions.push({
    type: 'request_documents',
    documents: demanded.map(d => d.name_de),
  });
}
if (artifacts.mandant_notification) {
  nextActions.push({
    type: 'create_client_draft',
    draft: artifacts.mandant_notification,
  });
}
if (artifacts.anwalt_response) {
  nextActions.push({
    type: 'create_authority_draft',
    draft: artifacts.anwalt_response,
  });
}

return [{
  json: {
    engine: 'gitlaw-outcome-engine',
    engine_version: '0.1.0',
    execution_id: $execution.id,
    source_document_id: intake.source_document_id,
    original_filename: intake.original_filename,
    review_required: true,
    auto_send_allowed: false,
    risk: blockers.length ? 'blocked' : (warnings.length ? 'review' : 'standard_review'),
    blockers,
    warnings,
    extracted: {
      meta: artifacts.meta ?? null,
      matched_case: matched,
      classification,
      required_documents: demanded,
      deadline,
    },
    drafts: {
      client: artifacts.mandant_notification ?? null,
      authority: artifacts.anwalt_response ?? null,
    },
    next_actions: nextActions,
    evidence: {
      agent_run_id: response.agent_run_id ?? null,
      status: response.status ?? 'unknown',
      iterations: response.iterations ?? null,
      total_cost_usd: response.total_cost_usd ?? null,
      tool_trace: response.tool_trace ?? [],
    },
    approval_request: {
      decision_required: true,
      allowed_decisions: ['approve', 'revise', 'reject'],
      resume_url: $execution.resumeUrl,
    },
    created_at: new Date().toISOString(),
  }
}];

const callback = $json.body ?? $json;
const packet = $('Build Review Packet').first().json;
const decision = String(callback.decision ?? '').toLowerCase();

if (!['approve', 'revise', 'reject'].includes(decision)) {
  throw new Error('Human decision must be approve, revise, or reject');
}

return [{
  json: {
    ...packet,
    human_review: {
      decision,
      reviewer_id: callback.reviewer_id ?? 'unknown',
      comment: callback.comment ?? null,
      reviewed_at: new Date().toISOString(),
    }
  }
}];
